LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        return lb;
    }
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            lb = ensureCapacity(1, lb);
            lb.buffer[lb.offset++] = (byte) c;
        } else if (c < 0x800) {
            lb = ensureCapacity(2, lb);
            lb.buffer[lb.offset++] = (byte) (0xc0 | (c >> 6));
            lb.buffer[lb.offset++] = (byte) (0x80 | (c & 0x3f));
        } else if (c < 0xd800 || c > 0xdfff) {
            lb = ensureCapacity(3, lb);
            lb.buffer[lb.offset++] = (byte) (0xe0 | (c >> 12));
            lb.buffer[lb.offset++] = (byte) (0x80 | ((c >> 6) & 0x3f));
            lb.buffer[lb.offset++] = (byte) (0x80 | (c & 0x3f));
        } else {
            if (i + 1 < len) {
                char c2 = str.charAt(++i);
                int uc = ((c - 0xd800) << 10) + (c2 - 0xdc00) + 0x10000;
                lb = ensureCapacity(4, lb);
                lb.buffer[lb.offset++] = (byte) (0xf0 | (uc >> 18));
                lb.buffer[lb.offset++] = (byte) (0x80 | ((uc >> 12) & 0x3f));
                lb.buffer[lb.offset++] = (byte) (0x80 | ((uc >> 6) & 0x3f));
                lb.buffer[lb.offset++] = (byte) (0x80 | (uc & 0x3f));
            }
        }
    }
    return lb;
}

LinkedBuffer ensureCapacity(final int required, final LinkedBuffer lb) {
    if (lb.offset + required > lb.length) {
        final int size = Math.max(lb.length << 1, lb.offset + required);
        final LinkedBuffer next = new LinkedBuffer(size);
        next.next = lb.next;
        System.arraycopy(lb.buffer, 0, next.buffer, 0, lb.offset);
        lb.next = next;
        lb = next;
    }
    return lb;
}

